    private static String textOf(WebDriver driver, By by) {
        WebElement e = Find.visibleOrReveal(driver, by);
        try {
            return e == null ? null : e.getText();
        } catch (WebDriverException gone) {
            return null;
        }
    }

    private static String valueOf(WebDriver driver, By by) {
        WebElement e = Find.visibleOrReveal(driver, by);
        try {
            if (e == null) return null;
            // A dropdown holds the option it shows, by its words, as choose() picks it.
            if ("select".equalsIgnoreCase(e.getTagName())) return String.valueOf(((JavascriptExecutor) driver).executeScript("return arguments[0].selectedOptions[0] ? arguments[0].selectedOptions[0].text : '';", e));
            return e.getDomProperty("value");
        } catch (WebDriverException gone) {
            return null;
        }
    }

    private static int countOf(WebDriver driver, By all) {
        int shown = 0;
        try {
            Frames.page(driver);
            for (WebElement e : driver.findElements(all)) {
                if (Find.isShown(e)) shown++;
            }
        } catch (org.openqa.selenium.InvalidSelectorException e) {
            throw Find.invalid(all, e);
        } catch (WebDriverException e) {
            return 0;
        }
        return shown;
    }

